// ✅ Always use parameterized queries:
const users = await db.query('SELECT id, name, email FROM users WHERE id = $1', [req.params.id]);

// ✅ Or use an ORM like Prisma / Sequelize which parameterizes by default:
const user = await prisma.user.findUnique({ where: { id: Number(req.params.id) } });
```

