const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()      // structured logs for log aggregators (Datadog, etc.)
  ),
  transports: [new winston.transports.Console()],
});

// Replace console.log
// console.log('Server running...') → logger.info('Server running...', { port: PORT });

// Catch-all error handler — MUST be defined with 4 args and placed LAST
app.use((err, req, res, next) => {
  // Log the full error internally
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    method: req.method,
    url: req.originalUrl,
    ip: req.ip,
