JWT_SECRET=a-long-random-string-here
```

---

## 🟡 Medium Severity Issues

### 7. No CORS Policy (OWASP A05 – Security Misconfiguration)
Without explicit CORS configuration, cross-origin behavior is unpredictable and potentially exploitable.

**Recommendation:** Use the `cors` package with an explicit allowlist.

```js
const cors = require('cors');

const corsOptions = {
  origin: (origin, callback) => {
    const allowlist = ['https://yourdomain.com'];
    if (!origin || allowlist.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));
```

---

### 8. No Centralized Error Handling (Information Leakage Risk)
Unhandled errors in Express will leak stack traces to the client in development, and may cause unhandled crashes in production.

**Recommendation:** Add a centralized error handler and a 404 catch-all.

```js
// 404 handler — must come after all routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Centralized error handler — must be last, with 4 args
app.use((err, req, res, next) => {
  console.error(err.stack); // Log internally
  const statusCode = err.status || 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred'
      : err.message, // Only expose detail in dev
  });
});
```

