### Example: AWS Secrets Manager (recommended pattern)

```js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

async function getSecret(secretName) {
  const response = await client.send(
    new GetSecretValueCommand({ SecretId: secretName })
  );
  return JSON.parse(response.SecretString);
}

// Load secrets before starting the server
async function startApp() {
  const secrets = await getSecret('myapp/production');

  const JWT_SECRET = secrets.JWT_SECRET;
  const DB_PASSWORD = secrets.DB_PASSWORD;

  // Now initialize app with secrets in memory only — never on disk
  app.listen(process.env.PORT || 3000);
}

