**Recommendation:** Add an authentication middleware. Here's a JWT-based example:

```js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Apply to protected routes
app.get('/users', authenticate, (req, res) => { ... });
```

---

### 🔴 CRITICAL — Sensitive Data Exposure

**Finding:** Email addresses (and potentially other PII) are returned to all callers without any access control. Even with auth added, the response should only include the minimum necessary fields.

**OWASP Reference:** [A02:2021 – Cryptographic Failures / Sensitive Data Exposure](https://owasp.org/Top10/A02_2021-Cryptographic_Failures/)

**Recommendation:** Apply field-level filtering and return only what clients need:

```js
app.get('/users', authenticate, (req, res) => {
  const users = getAllUsers(); // from DB
  const safeUsers = users.map(({ id, name }) => ({ id, name })); // omit email, etc.
  res.json(safeUsers);
});
```

