app.use(helmet());
// Sets: X-Frame-Options, X-Content-Type-Options, Strict-Transport-Security,
//       Content-Security-Policy, X-XSS-Protection, Referrer-Policy, and more.
```

---

### 🟠 HIGH — No Rate Limiting

**Finding:** All endpoints, including `/users`, are unthrottled. This enables brute-force attacks, credential stuffing (once auth is added), and denial-of-service.

**OWASP Reference:** [A04:2021 – Insecure Design](https://owasp.org/Top10/A04_2021-Insecure_Design/)

**Recommendation:** Add `express-rate-limit`:

```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

