function logSecurityEvent(event, req, extra = {}) {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    event,
    ip: req.ip,
    method: req.method,
    path: req.path,
    userAgent: req.headers['user-agent'],
