app.use((err, req, res, next) => {
  // Log full detail internally
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
  });

  // Return only a safe, generic message externally
  const status = err.status || err.statusCode || 500;
  res.status(status).json({
