  res.json([{ id: 1, name: 'Alice', email: 'alice@example.com' }, ...]);
});
```

**Fix:** Add authentication middleware (e.g., JWT verification) before any data-returning route.

```js
// ✅ RECOMMENDED
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }
  try {
    req.user = jwt.verify(auth.slice(7), process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

app.get('/users', requireAuth, (req, res) => { ... });
```

---

### 2. Secrets in `.env.test` Must Not Be Committed

**Issue:** `.env.test` contains database URLs, cloud provider keys, an Anthropic API key, and a live Stripe key. Even "canary" values in a committed file are a liability — they train developers to treat secrets carelessly and can be mistaken for real credentials by automated scanners or bad actors. This maps to **OWASP A02 – Cryptographic Failures** (secrets mismanagement).

**Fix:**

```bash
